const buildPositiveOnlyPrompt = (prompt: ArtisanSamPromptBuild): ArtisanSamPromptBuild | null => {
    const points = prompt.points.filter(point => point.label === 1);
    if (points.length === 0 || prompt.negativeCount === 0) {
        return null;
    }

    return {
        ...prompt,
        points,
        positiveCount: points.length,
        negativeCount: 0
    };
};

