const trimBase64DataUrl = (value: string) => {
    const commaIndex = value.indexOf(',');
    return value.startsWith('data:') && commaIndex >= 0 ? value.slice(commaIndex + 1) : value;
};

const createRunId = () => {
    return `artisan-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
};

const getSplatKey = (splat: Splat) => {
    return `${splat.filename}:${splat.splatData.numSplats}`;
};

const cloneStatus = (status: ArtisanLocalStatus): ArtisanLocalStatus => ({ ...status });

const countSelectedSplats = (splat: Splat) => {
    const state = splat.splatData.getProp('state') as Uint8Array;
    let selected = 0;
    for (let i = 0; i < state.length; i++) {
        if ((state[i] & State.selected) !== 0) selected++;
    }
    return selected;
};

const applyIndexOp = (base: Set<number>, op: ArtisanSelectionMode, indices: Set<number>) => {
    if (op === 'set') {
        return new Set(indices);
    }

    const next = new Set(base);
    if (op === 'add') {
        for (const idx of indices) next.add(idx);
    } else if (op === 'remove') {
        for (const idx of indices) next.delete(idx);
    } else {
        for (const idx of Array.from(next)) {
            if (!indices.has(idx)) next.delete(idx);
        }
    }
    return next;
};

const encodeIndexRanges = (indices: Set<number>): [number, number][] => {
    const sorted = Array.from(indices).sort((a, b) => a - b);
    const ranges: [number, number][] = [];
    let start = -1;
    let end = -1;

    for (const idx of sorted) {
        if (start < 0) {
            start = idx;
            end = idx;
        } else if (idx === end + 1) {
            end = idx;
        } else {
            ranges.push([start, end]);
            start = idx;
            end = idx;
        }
    }

    if (start >= 0) {
        ranges.push([start, end]);
    }

    return ranges;
};

const decodeIndexRanges = (ranges: [number, number][], maxIndex: number) => {
    const indices = new Set<number>();
    for (const [start, end] of ranges) {
        for (let idx = Math.max(0, start); idx <= Math.min(maxIndex, end); idx++) {
            indices.add(idx);
        }
    }
    return indices;
};

const isFiniteNumber = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value);

const isFiniteTuple3 = (value: unknown): value is [number, number, number] => (
    Array.isArray(value) &&
    value.length === 3 &&
    value.every(isFiniteNumber)
);

const parseArtisanEvalPrimarySelection = (value: unknown): ArtisanEvalPrimarySelection | null => {
    if (typeof value !== 'string') {
        return null;
    }

    return ARTISAN_EVAL_PRIMARY_SELECTIONS.includes(value as ArtisanEvalPrimarySelection) ?
        value as ArtisanEvalPrimarySelection :
        null;
};

const isArtisanEvalTarget = (value: unknown): value is ArtisanEvalTarget => {
    const target = value as ArtisanEvalTarget | null | undefined;
    return !!target &&
        target.type === 'axis_aligned_box' &&
        isFiniteTuple3(target.center) &&
        isFiniteTuple3(target.dimensions) &&
        target.dimensions.every(dimension => dimension > 0) &&
        Array.isArray(target.rotation);
};

const cloneCameraState = (camera: CameraDebugState): CameraDebugState => ({
    position: { ...camera.position },
    target: { ...camera.target },
    fov: camera.fov,
    azim: camera.azim,
    elevation: camera.elevation,
    distance: camera.distance,
    ortho: camera.ortho
});

const cloneArtisanEvalTarget = (target: ArtisanEvalTarget): ArtisanEvalTarget => ({
    type: 'axis_aligned_box',
    center: [...target.center] as [number, number, number],
    dimensions: [...target.dimensions] as [number, number, number],
    rotation: target.rotation.map(row => Array.isArray(row) ? [...row] : []),
    ready: target.ready,
    updated_at: target.updated_at,
    source: target.source,
    touched: target.touched,
    confirmed: target.confirmed,
    confirmed_at: target.confirmed_at,
    confirmation_attempted_at: target.confirmation_attempted_at,
    changed_from_initial: target.changed_from_initial,
    active: target.active,
    synthetic: target.synthetic,
    screen_points: target.screen_points?.map(point => [...point] as [number, number]),
    screen_size: target.screen_size ? { ...target.screen_size } : undefined,
    camera: target.camera ? cloneCameraState(target.camera) : undefined,
    selected_count: target.selected_count,
    selected_ranges: target.selected_ranges?.map(range => [...range] as [number, number]),
    projection_mode: target.projection_mode,
    capture_id: target.capture_id
});

const cloneKnownDeskCanEvalTarget = (): ArtisanEvalTarget => cloneArtisanEvalTarget(ARTISAN_KNOWN_DESK_CAN_TARGET);

const evalTargetFromTargetBounds = (
    bounds: ArtisanTargetBounds | ArtisanExpandedTargetBounds | null | undefined,
    source: string,
    synthetic = true
): ArtisanEvalTarget | null => {
    if (!bounds?.center || !bounds.min || !bounds.max) {
        return null;
    }

    const center: [number, number, number] = [bounds.center.x, bounds.center.y, bounds.center.z];
    const min: [number, number, number] = [bounds.min.x, bounds.min.y, bounds.min.z];
    const max: [number, number, number] = [bounds.max.x, bounds.max.y, bounds.max.z];
    if (![...center, ...min, ...max].every(Number.isFinite)) {
        return null;
    }

    const dimensions: [number, number, number] = [
        Math.max(1e-6, max[0] - min[0]),
        Math.max(1e-6, max[1] - min[1]),
        Math.max(1e-6, max[2] - min[2])
    ];
    return {
        type: 'axis_aligned_box',
        center,
        dimensions,
        rotation: [
            [1, 0, 0],
            [0, 1, 0],
            [0, 0, 1]
        ],
        ready: true,
        updated_at: new Date().toISOString(),
        source,
        touched: true,
        confirmed: true,
        confirmed_at: new Date().toISOString(),
        changed_from_initial: true,
        synthetic
    };
};

const isReadyArtisanEvalTarget = (target: unknown): target is ArtisanEvalTarget => (
    isArtisanEvalTarget(target) && target.ready !== false
);

const artisanEvalTargetError = (target: unknown, fallback?: string) => {
    if (isArtisanEvalTarget(target) && target.ready === false) {
        return ARTISAN_EVAL_TARGET_UNREADY_ERROR;
    }
    return fallback;
};

const getArtisanEvalTargetAxes = (rotation: number[][]): [number, number, number][] => {
    const axes: [number, number, number][] = [];
    for (let col = 0; col < 3; col++) {
        const axis: [number, number, number] = [
            Number(rotation[0]?.[col] ?? (col === 0 ? 1 : 0)),
            Number(rotation[1]?.[col] ?? (col === 1 ? 1 : 0)),
            Number(rotation[2]?.[col] ?? (col === 2 ? 1 : 0))
        ];
        const length = Math.hypot(axis[0], axis[1], axis[2]);
        axes.push(length > 1e-6 ? [
            axis[0] / length,
            axis[1] / length,
            axis[2] / length
        ] : [
            col === 0 ? 1 : 0,
            col === 1 ? 1 : 0,
            col === 2 ? 1 : 0
        ]);
    }
    return axes;
};

const artisanEvalTargetContainsPoint = (target: ArtisanEvalTarget, x: number, y: number, z: number) => {
    const axes = getArtisanEvalTargetAxes(target.rotation);
    const dx = x - target.center[0];
    const dy = y - target.center[1];
    const dz = z - target.center[2];
    const epsilon = 1e-5;

    for (let axisIndex = 0; axisIndex < 3; axisIndex++) {
        const axis = axes[axisIndex];
        const local = dx * axis[0] + dy * axis[1] + dz * axis[2];
        if (Math.abs(local) > target.dimensions[axisIndex] * 0.5 + epsilon) {
            return false;
        }
    }

    return true;
};

const axisAlignedEvalBox = (target: ArtisanEvalTarget) => {
    const halfX = target.dimensions[0] * 0.5;
    const halfY = target.dimensions[1] * 0.5;
    const halfZ = target.dimensions[2] * 0.5;
    const min = {
        x: target.center[0] - halfX,
        y: target.center[1] - halfY,
        z: target.center[2] - halfZ
    };
    const max = {
        x: target.center[0] + halfX,
        y: target.center[1] + halfY,
        z: target.center[2] + halfZ
    };
    return {
        center: { x: target.center[0], y: target.center[1], z: target.center[2] },
        min,
        max,
        radius: Math.hypot(halfX, halfY, halfZ),
        volume: Math.max(0, target.dimensions[0] * target.dimensions[1] * target.dimensions[2])
    };
};

const axisAlignedTargetBoundsBox = (bounds: ArtisanTargetBounds | ArtisanExpandedTargetBounds | null | undefined) => {
    const center = bounds?.center;
    if (!center || !Number.isFinite(center.x) || !Number.isFinite(center.y) || !Number.isFinite(center.z)) {
        return null;
    }

    const radius = Math.max(0.04, bounds.radius ?? 0.04);
    const min = bounds.min &&
        Number.isFinite(bounds.min.x) &&
        Number.isFinite(bounds.min.y) &&
        Number.isFinite(bounds.min.z) ? bounds.min : {
            x: center.x - radius,
            y: center.y - radius,
            z: center.z - radius
        };
    const max = bounds.max &&
        Number.isFinite(bounds.max.x) &&
        Number.isFinite(bounds.max.y) &&
        Number.isFinite(bounds.max.z) ? bounds.max : {
            x: center.x + radius,
            y: center.y + radius,
            z: center.z + radius
        };
    const volume = Math.max(0, max.x - min.x) *
        Math.max(0, max.y - min.y) *
        Math.max(0, max.z - min.z);
    return { center, min, max, radius, volume };
};

const pointInsideAxisAlignedBox = (
    point: { x: number; y: number; z: number },
    box: { min: { x: number; y: number; z: number }; max: { x: number; y: number; z: number } }
) => (
    point.x >= box.min.x && point.x <= box.max.x &&
    point.y >= box.min.y && point.y <= box.max.y &&
    point.z >= box.min.z && point.z <= box.max.z
);

const axisAlignedIntersectionVolume = (
    a: { min: { x: number; y: number; z: number }; max: { x: number; y: number; z: number } },
    b: { min: { x: number; y: number; z: number }; max: { x: number; y: number; z: number } }
) => {
    const dx = Math.max(0, Math.min(a.max.x, b.max.x) - Math.max(a.min.x, b.min.x));
    const dy = Math.max(0, Math.min(a.max.y, b.max.y) - Math.max(a.min.y, b.min.y));
    const dz = Math.max(0, Math.min(a.max.z, b.max.z) - Math.max(a.min.z, b.min.z));
    return dx * dy * dz;
};

const compareEvalTargetToAlgorithmBounds = (
    target: ArtisanEvalTarget,
    algorithmBounds: ArtisanTargetBounds | ArtisanExpandedTargetBounds | null | undefined,
    source: ArtisanEvalBoundsComparison['algorithm_bounds_source']
): ArtisanEvalBoundsComparison | undefined => {
    const evalBox = axisAlignedEvalBox(target);
    const algorithmBox = axisAlignedTargetBoundsBox(algorithmBounds);
    if (!algorithmBox || evalBox.volume <= 0 || algorithmBox.volume <= 0) {
        return undefined;
    }

    const intersectionVolume = axisAlignedIntersectionVolume(evalBox, algorithmBox);
    const centerDistance = Math.hypot(
        evalBox.center.x - algorithmBox.center.x,
        evalBox.center.y - algorithmBox.center.y,
        evalBox.center.z - algorithmBox.center.z
    );
    const radiusRatio = evalBox.radius > 0 ? algorithmBox.radius / evalBox.radius : Number.POSITIVE_INFINITY;

    return {
        algorithm_bounds_source: source,
        center_distance: centerDistance,
        eval_radius: evalBox.radius,
        algorithm_radius: algorithmBox.radius,
        radius_ratio: radiusRatio,
        eval_box_volume: evalBox.volume,
        algorithm_box_volume: algorithmBox.volume,
        intersection_volume: intersectionVolume,
        eval_volume_covered_ratio: intersectionVolume / evalBox.volume,
        algorithm_volume_inside_eval_ratio: intersectionVolume / algorithmBox.volume,
        eval_center_inside_algorithm: pointInsideAxisAlignedBox(evalBox.center, algorithmBox),
        algorithm_center_inside_eval: pointInsideAxisAlignedBox(algorithmBox.center, evalBox)
    };
};

const selectedIndicesFromSplatState = (splat: Splat) => {
    const indices = new Set<number>();
    const state = splat.splatData.getProp('state') as Uint8Array | undefined;
    const total = splat.splatData.numSplats;
    if (!state) {
        return indices;
    }

    for (let i = 0; i < Math.min(total, state.length); i++) {
        if ((state[i] & State.deleted) === 0 && (state[i] & State.selected) !== 0) {
            indices.add(i);
        }
    }

    return indices;
};

const indicesFromConfidenceValues = (confidence: Float32Array | undefined, minConfidence: number) => {
    const indices = new Set<number>();
    if (!confidence) {
        return indices;
    }

    for (let i = 0; i < confidence.length; i++) {
        if (confidence[i] >= minConfidence) {
            indices.add(i);
        }
    }
    return indices;
};

const indicesFromPosteriorEvidenceValues = (
    confidence: Float32Array | undefined,
    positiveEvidence: Float32Array | undefined,
    observedEvidence: Float32Array | undefined,
    minConfidence: number,
    minPositiveRatio = BAYES_FINAL_MIN_POSITIVE_RATIO,
    minObserved = BAYES_MIN_OBSERVED_EVIDENCE,
    minPositive = BAYES_MIN_POSITIVE_EVIDENCE
) => {
    const indices = new Set<number>();
    if (!confidence || !positiveEvidence || !observedEvidence) {
        return indices;
    }

    const total = Math.min(confidence.length, positiveEvidence.length, observedEvidence.length);
    for (let i = 0; i < total; i++) {
        const observed = observedEvidence[i];
        const positive = positiveEvidence[i];
        const positiveRatio = observed > 0 ? positive / observed : 0;
        if (confidence[i] >= minConfidence &&
            observed >= minObserved &&
            positive >= minPositive &&
            positiveRatio >= minPositiveRatio) {
            indices.add(i);
        }
    }
    return indices;
};

const aggregationConfidenceFromObject = (object: ArtisanObjectState): ArtisanConfidenceStats | undefined => (
    (object.metrics as { stats?: { confidence?: ArtisanConfidenceStats } } | undefined)?.stats?.confidence
);

const indicesFromAlgorithmTargetBoundedPosterior = (
    splat: Splat,
    object: ArtisanObjectState,
    minConfidence: number
) => {
    const confidence = object.confidence;
    const positiveEvidence = object.posterior_positive;
    const observedEvidence = object.posterior_observed;
    const stats = aggregationConfidenceFromObject(object);
    if (!confidence || !positiveEvidence || !observedEvidence) {
        return new Set<number>();
    }

    const targetContains = stats?.target_bounds ?
        createExpandedTargetBoundsPredicate(splat, stats.target_bounds) :
        null;
    const indices = new Set<number>();
    const total = Math.min(confidence.length, positiveEvidence.length, observedEvidence.length);
    const minPositiveRatio = stats?.final_min_positive_ratio ?? BAYES_FINAL_MIN_POSITIVE_RATIO;
    const minObserved = stats?.min_votes ?? BAYES_MIN_OBSERVED_EVIDENCE;
    const minPositive = stats?.min_positive_votes ?? BAYES_MIN_POSITIVE_EVIDENCE;
    for (let i = 0; i < total; i++) {
        const observed = observedEvidence[i];
        const positive = positiveEvidence[i];
        const positiveRatio = observed > 0 ? positive / observed : 0;
        if (confidence[i] >= minConfidence &&
            observed >= minObserved &&
            positive >= minPositive &&
            positiveRatio >= minPositiveRatio &&
            (!targetContains || targetContains(i))) {
            indices.add(i);
        }
    }
    return indices;
};

const indicesFromAlgorithmTargetVolume = (
    splat: Splat,
    object: ArtisanObjectState
) => {
    const stats = aggregationConfidenceFromObject(object);
    const bounds = stats?.target_bounds;
    const centers = splat.entity.gsplat?.instance?.sorter?.centers as Float32Array | undefined;
    if (!centers || !isUsableTargetBounds(bounds)) {
        return new Set<number>();
    }

    const radius = Math.max(0.04, bounds.radius ?? 0.04);
    const min = targetBoundsMin(bounds, radius);
    const max = targetBoundsMax(bounds, radius);
    const world = splat.entity.getWorldTransform().data as Float32Array;
    const state = splat.splatData.getProp('state') as Uint8Array | undefined;
    const total = Math.min(splat.splatData.numSplats, centers.length / 3);
    const indices = new Set<number>();
    for (let i = 0; i < total; i++) {
        if (state && (state[i] & State.deleted) !== 0) {
            continue;
        }

        const lx = centers[i * 3];
        const ly = centers[i * 3 + 1];
        const lz = centers[i * 3 + 2];
        const wx = world[0] * lx + world[4] * ly + world[8]  * lz + world[12];
        const wy = world[1] * lx + world[5] * ly + world[9]  * lz + world[13];
        const wz = world[2] * lx + world[6] * ly + world[10] * lz + world[14];
        if (wx >= min.x && wx <= max.x &&
            wy >= min.y && wy <= max.y &&
            wz >= min.z && wz <= max.z) {
            indices.add(i);
        }
    }
    return indices;
};

const buildEvalSelectionMetrics = (
    label: string,
    selected: Set<number>,
    targetInside: Set<number>,
    thresholds: ArtisanEvalThresholds
): ArtisanEvalSelectionMetrics => {
    const selectedInside = new Set<number>();
    const falsePositive = new Set<number>();
    const falseNegative = new Set<number>();

    for (const idx of selected) {
        if (targetInside.has(idx)) {
            selectedInside.add(idx);
        } else {
            falsePositive.add(idx);
        }
    }

    for (const idx of targetInside) {
        if (!selected.has(idx)) {
            falseNegative.add(idx);
        }
    }

    const precision = selected.size > 0 ? selectedInside.size / selected.size : null;
    const targetRecall = targetInside.size > 0 ? selectedInside.size / targetInside.size : null;
    const pass = precision !== null &&
        targetRecall !== null &&
        precision >= thresholds.selected_precision_at_least &&
        targetRecall >= thresholds.target_recall_at_least;

    return {
        label,
        selected_count: selected.size,
        selected_inside_target_count: selectedInside.size,
        target_inside_count: targetInside.size,
        false_positive_count: falsePositive.size,
        false_negative_count: falseNegative.size,
        precision,
        target_recall: targetRecall,
        pass,
        selected_ranges: encodeIndexRanges(selected),
        selected_inside_target_ranges: encodeIndexRanges(selectedInside),
        false_positive_ranges: encodeIndexRanges(falsePositive),
        false_negative_ranges: encodeIndexRanges(falseNegative)
    };
};

const summarizeEvalSelection = (
    metrics: ArtisanEvalSelectionMetrics,
    threshold?: number,
    options: Partial<Pick<
        ArtisanEvalSelectionSummary,
        'confidence_threshold' | 'positive_ratio_threshold' | 'min_observed_evidence' | 'min_positive_evidence'
    >> = {}
): ArtisanEvalSelectionSummary => ({
    label: metrics.label,
    selected_count: metrics.selected_count,
    selected_inside_target_count: metrics.selected_inside_target_count,
    target_inside_count: metrics.target_inside_count,
    false_positive_count: metrics.false_positive_count,
    false_negative_count: metrics.false_negative_count,
    precision: metrics.precision,
    target_recall: metrics.target_recall,
    pass: metrics.pass,
    threshold,
    ...options
});

const compareEvalSelectionSummaries = (
    thresholds: ArtisanEvalThresholds,
    a: ArtisanEvalSelectionSummary,
    b: ArtisanEvalSelectionSummary
) => {
    if (a.pass !== b.pass) {
        return a.pass ? -1 : 1;
    }

    const aPrecision = a.precision ?? -1;
    const bPrecision = b.precision ?? -1;
    const aRecall = a.target_recall ?? -1;
    const bRecall = b.target_recall ?? -1;
    const aPrecisionShortfall = Math.max(0, thresholds.selected_precision_at_least - aPrecision);
    const bPrecisionShortfall = Math.max(0, thresholds.selected_precision_at_least - bPrecision);
    const aRecallShortfall = Math.max(0, thresholds.target_recall_at_least - aRecall);
    const bRecallShortfall = Math.max(0, thresholds.target_recall_at_least - bRecall);
    const aShortfall = aPrecisionShortfall * 1.25 + aRecallShortfall;
    const bShortfall = bPrecisionShortfall * 1.25 + bRecallShortfall;
    if (aShortfall !== bShortfall) {
        return aShortfall - bShortfall;
    }
    if (aPrecision !== bPrecision) {
        return bPrecision - aPrecision;
    }
    if (aRecall !== bRecall) {
        return bRecall - aRecall;
    }
    return (a.selected_count ?? 0) - (b.selected_count ?? 0);
};

const evaluateArtisanBoxSelection = (
    splat: Splat,
    object: ArtisanObjectState,
    target: ArtisanEvalTarget,
    thresholds: ArtisanEvalThresholds = ARTISAN_EVAL_DEFAULT_THRESHOLDS,
    options: { primarySelection?: unknown } = {}
): ArtisanEvalBoxMetrics => {
    const centers = splat.entity.gsplat?.instance?.sorter?.centers as Float32Array | undefined;
    if (!centers) {
        return {
            ok: false,
            error: 'Splat center buffer is unavailable',
            thresholds,
            primary_selection: 'editor_state'
        };
    }

    const world = splat.entity.getWorldTransform().data as Float32Array;
    const state = splat.splatData.getProp('state') as Uint8Array | undefined;
    const total = Math.min(splat.splatData.numSplats, centers.length / 3);
    const targetInside = new Set<number>();
    let deletedCount = 0;

    for (let i = 0; i < total; i++) {
        if (state && (state[i] & State.deleted) !== 0) {
            deletedCount++;
            continue;
        }

        const lx = centers[i * 3];
        const ly = centers[i * 3 + 1];
        const lz = centers[i * 3 + 2];
        const wx = world[0] * lx + world[4] * ly + world[8]  * lz + world[12];
        const wy = world[1] * lx + world[5] * ly + world[9]  * lz + world[13];
        const wz = world[2] * lx + world[6] * ly + world[10] * lz + world[14];
        if (artisanEvalTargetContainsPoint(target, wx, wy, wz)) {
            targetInside.add(i);
        }
    }

    const confidenceThreshold = object.confidence_threshold ?? DEFAULT_CONFIDENCE_THRESHOLD;
    const aggregationConfidence = aggregationConfidenceFromObject(object);
    const adaptiveThreshold = aggregationConfidence?.threshold ?? confidenceThreshold;
    const baseThreshold = aggregationConfidence?.final_min_confidence_threshold ?? BAYES_FINAL_MIN_CONFIDENCE_THRESHOLD;
    const looseThreshold = aggregationConfidence?.requested_threshold ?? confidenceThreshold;
    const selections: Record<ArtisanEvalPrimarySelection, ArtisanEvalSelectionMetrics> = {
        editor_state: buildEvalSelectionMetrics(
            'editor_state',
            selectedIndicesFromSplatState(splat),
            targetInside,
            thresholds
        ),
        object_selected: buildEvalSelectionMetrics(
            'object_selected',
            new Set(object.selected),
            targetInside,
            thresholds
        ),
        target_bounded_posterior: buildEvalSelectionMetrics(
            'target_bounded_posterior',
            new Set(object.selected),
            targetInside,
            thresholds
        ),
        target_bounded_adaptive: buildEvalSelectionMetrics(
            'target_bounded_adaptive',
            indicesFromAlgorithmTargetBoundedPosterior(splat, object, adaptiveThreshold),
            targetInside,
            thresholds
        ),
        target_bounded_base: buildEvalSelectionMetrics(
            'target_bounded_base',
            indicesFromAlgorithmTargetBoundedPosterior(splat, object, baseThreshold),
            targetInside,
            thresholds
        ),
        target_bounded_loose: buildEvalSelectionMetrics(
            'target_bounded_loose',
            indicesFromAlgorithmTargetBoundedPosterior(splat, object, looseThreshold),
            targetInside,
            thresholds
        ),
        target_volume: buildEvalSelectionMetrics(
            'target_volume',
            indicesFromAlgorithmTargetVolume(splat, object),
            targetInside,
            thresholds
        ),
        final_thresholded: buildEvalSelectionMetrics(
            'final_thresholded',
            new Set(object.final_selected ?? []),
            targetInside,
            thresholds
        ),
        all_voted: buildEvalSelectionMetrics(
            'all_voted',
            new Set(object.voted ?? []),
            targetInside,
            thresholds
        ),
        confidence_thresholded: buildEvalSelectionMetrics(
            'confidence_thresholded',
            indicesFromConfidenceValues(object.confidence, confidenceThreshold),
            targetInside,
            thresholds
        ),
        posterior_filtered: buildEvalSelectionMetrics(
            'posterior_filtered',
            indicesFromPosteriorEvidenceValues(
                object.confidence,
                object.posterior_positive,
                object.posterior_observed,
                confidenceThreshold
            ),
            targetInside,
            thresholds
        )
    };
    const fallbackPrimarySelection: ArtisanEvalPrimarySelection = object.selected.size > 0 ?
        ARTISAN_EVAL_DEFAULT_PRIMARY_SELECTION :
        ((object.final_selected?.size ?? 0) > 0 ? 'final_thresholded' : 'editor_state');
    const primarySelection = parseArtisanEvalPrimarySelection(options.primarySelection) ?? fallbackPrimarySelection;
    const sweepThresholds = Array.from(new Set([
        confidenceThreshold,
        adaptiveThreshold,
        baseThreshold,
        looseThreshold,
        ...ARTISAN_EVAL_CONFIDENCE_SWEEP_THRESHOLDS
    ]))
    .map(value => Math.max(0.01, Math.min(0.99, Number(value))))
    .filter(Number.isFinite)
    .sort((a, b) => a - b);
    const confidenceThresholdSweep = sweepThresholds.map((threshold) => {
        const roundedThreshold = Number(threshold.toFixed(3));
        return summarizeEvalSelection(
            buildEvalSelectionMetrics(
                `confidence_threshold_${roundedThreshold}`,
                indicesFromConfidenceValues(object.confidence, threshold),
                targetInside,
                thresholds
            ),
            roundedThreshold
        );
    });
    const bestConfidenceThreshold = confidenceThresholdSweep
    .slice()
    .sort((a, b) => compareEvalSelectionSummaries(thresholds, a, b))[0];
    const posteriorFilterSweep = sweepThresholds.map((threshold) => {
        const roundedThreshold = Number(threshold.toFixed(3));
        return summarizeEvalSelection(
            buildEvalSelectionMetrics(
                `posterior_filter_${roundedThreshold}`,
                indicesFromPosteriorEvidenceValues(
                    object.confidence,
                    object.posterior_positive,
                    object.posterior_observed,
                    threshold
                ),
                targetInside,
                thresholds
            ),
            roundedThreshold,
            {
                confidence_threshold: roundedThreshold,
                positive_ratio_threshold: BAYES_FINAL_MIN_POSITIVE_RATIO,
                min_observed_evidence: BAYES_MIN_OBSERVED_EVIDENCE,
                min_positive_evidence: BAYES_MIN_POSITIVE_EVIDENCE
            }
        );
    });
    const bestPosteriorFilter = posteriorFilterSweep
    .slice()
    .sort((a, b) => compareEvalSelectionSummaries(thresholds, a, b))[0];
    const targetBoundedPosteriorSweep = sweepThresholds.map((threshold) => {
        const roundedThreshold = Number(threshold.toFixed(3));
        const stats = aggregationConfidenceFromObject(object);
        return summarizeEvalSelection(
            buildEvalSelectionMetrics(
                `target_bounded_posterior_${roundedThreshold}`,
                indicesFromAlgorithmTargetBoundedPosterior(splat, object, threshold),
                targetInside,
                thresholds
            ),
            roundedThreshold,
            {
                confidence_threshold: roundedThreshold,
                positive_ratio_threshold: stats?.final_min_positive_ratio ?? BAYES_FINAL_MIN_POSITIVE_RATIO,
                min_observed_evidence: stats?.min_votes ?? BAYES_MIN_OBSERVED_EVIDENCE,
                min_positive_evidence: stats?.min_positive_votes ?? BAYES_MIN_POSITIVE_EVIDENCE
            }
        );
    });
    const bestTargetBoundedPosterior = targetBoundedPosteriorSweep
    .slice()
    .sort((a, b) => compareEvalSelectionSummaries(thresholds, a, b))[0];
    const selectionSummaries = Object.fromEntries(
        Object.entries(selections).map(([key, value]) => [key, summarizeEvalSelection(value)])
    ) as Record<ArtisanEvalPrimarySelection, ArtisanEvalSelectionSummary>;
    const boundsComparison = aggregationConfidence?.target_bounds_expanded ?
        compareEvalTargetToAlgorithmBounds(target, aggregationConfidence.target_bounds_expanded, 'expanded') :
        compareEvalTargetToAlgorithmBounds(target, aggregationConfidence?.target_bounds, 'raw');

    return {
        ok: true,
        target_ready: target.ready !== false,
        target_source: target.source,
        target_inside_count: targetInside.size,
        target_inside_ranges: encodeIndexRanges(targetInside),
        splat_count: total,
        deleted_count: deletedCount,
        thresholds,
        primary_selection: primarySelection,
        primary: selections[primarySelection] ?? selections.editor_state,
        selections,
        selection_summaries: selectionSummaries,
        confidence_threshold_sweep: confidenceThresholdSweep,
        best_confidence_threshold: bestConfidenceThreshold,
        posterior_filter_sweep: posteriorFilterSweep,
        best_posterior_filter: bestPosteriorFilter,
        target_bounded_posterior_sweep: targetBoundedPosteriorSweep,
        best_target_bounded_posterior: bestTargetBoundedPosterior,
        bounds_comparison: boundsComparison
    };
};

const throwIfAborted = (signal?: AbortSignal) => {
    if (signal?.aborted) {
        throw new DOMException('Local ArtisanGS cancelled', 'AbortError');
    }
};

const yieldToBrowser = () => new Promise<void>(resolve => window.setTimeout(resolve, 0));
const delayMs = (ms: number) => new Promise<void>(resolve => window.setTimeout(resolve, ms));

const messageFromError = (err: unknown, fallback = 'Unknown error') => {
    if (err instanceof Error && err.message) {
        return err.message;
    }

    if (typeof err === 'string' && err.trim()) {
        return err;
    }

    return fallback;
};

const isTransientSam31CloudError = (message: string) => {
    return /fetch failed|network|timed out|timeout|abort|cuda.*out of memory|out of memory|502|503|504/i.test(message);
};

const sam31CloudRetryDelayMs = (message: string, attempt: number) => {
    const baseDelay = /cuda.*out of memory|out of memory/i.test(message) ?
        SAM31_CLOUD_STEP_OOM_RETRY_DELAY_MS :
        SAM31_CLOUD_STEP_RETRY_DELAY_MS;
    return baseDelay * attempt;
};

