const getUrlToggle = (name: string, defaultValue: boolean) => {
    const value = new URLSearchParams(window.location.search).get(name);
    if (value === null) {
        return defaultValue;
    }

    const normalized = value.trim().toLowerCase();
    if (normalized === '') {
        return true;
    }

    return normalized !== '0' && normalized !== 'false' && normalized !== 'off' && normalized !== 'none' && normalized !== 'no';
};

