// Seed-relative "horrible mask" gate: the seed selection approximates object size, so a
// refined mask selecting more than this multiple of it is garbage (e.g. whole-frame mask)
// and is hard-rejected. Everything below the bar feeds the posterior (possibly downweighted).
const getMaskMaxSeedRatio = () => Math.max(1, getNumberUrlParam('artisanMaskMaxSeedRatio') ?? 3.5);

// Masks that fail soft quality checks are no longer discarded: they vote at this reduced
// weight so a couple of bad inputs are tolerated by the posterior instead of wasting views.
const getToleratedMaskWeight = () => Math.max(0, getNumberUrlParam('artisanToleratedMaskWeight') ?? 0.15);

// One reprojected SAM click per refined view (no negatives): project the seed selection
// into the view and click its most trusted central point. Disable with
// ?artisanSingleClickPrompt=0 to return to footprint-spread multi-point prompts.
const getSingleClickPromptEnabled = () => getUrlToggle('artisanSingleClickPrompt', true);

const getPosteriorExpansionRadiusScale = () => Math.max(
    1,
    getNumberUrlParam('artisanExpansionRadiusScale') ?? BAYES_EXPANSION_RADIUS_SCALE
);

const getPosteriorExpansionMinTrust = () => Math.max(
    0,
    getNumberUrlParam('artisanExpansionMinTrust') ?? BAYES_EXPANSION_MIN_TRUST
);

// The seed mask is human-generated (and reviewed/brush-fixed), so its positive evidence
// outweighs auto-generated refined views by this factor.
const getSeedEvidenceWeightScale = () => Math.max(
    1,
    getNumberUrlParam('artisanSeedEvidenceWeight') ?? BAYES_SEED_EVIDENCE_WEIGHT_SCALE
);

const quantileValue = (values: number[], quantile: number) => {
    if (values.length === 0) {
        return undefined;
    }

    const sorted = values.slice().sort((a, b) => a - b);
    const index = Math.min(
        sorted.length - 1,
        Math.max(0, Math.round((sorted.length - 1) * quantile))
    );
    return sorted[index];
};

const resolveAdaptiveFinalThreshold = (
    baseThreshold: number,
    candidateValues: number[],
    anchorValues: number[]
) => {
    const enabled = getFinalAdaptiveThresholdEnabled();
    const minCandidates = Math.max(8, getPositiveIntegerUrlParam('artisanFinalAdaptiveThresholdMinCandidates') ?? 256);
    const quantile = Math.max(0, Math.min(0.9, getNumberUrlParam('artisanFinalAdaptiveThresholdQuantile') ?? 0.35));
    const maxThreshold = Math.max(
        baseThreshold,
        Math.min(0.95, getNumberUrlParam('artisanFinalAdaptiveThresholdMax') ?? 0.68)
    );
    const minRaise = Math.max(0, getNumberUrlParam('artisanFinalAdaptiveThresholdMinRaise') ?? 0.025);
    const anchorMargin = Math.max(0, getNumberUrlParam('artisanFinalAdaptiveThresholdAnchorMargin') ?? 0.18);
    const quantileThreshold = candidateValues.length >= minCandidates ?
        quantileValue(candidateValues, quantile) :
        undefined;
    const anchorMedian = anchorValues.length > 0 ? quantileValue(anchorValues, 0.5) : undefined;
    const anchorFloor = anchorMedian !== undefined ? Math.max(baseThreshold, anchorMedian - anchorMargin) : undefined;
    const proposed = Math.max(
        baseThreshold,
        quantileThreshold ?? baseThreshold,
        anchorFloor ?? baseThreshold
    );
    const threshold = enabled && proposed >= baseThreshold + minRaise ?
        Math.min(maxThreshold, proposed) :
        baseThreshold;

    return {
        enabled,
        threshold,
        applied: threshold > baseThreshold,
        candidateCount: candidateValues.length,
        anchorCount: anchorValues.length,
        quantile,
        quantileThreshold,
        anchorFloor
    };
};

