const resolveCandidateCheckBudget = (frameCount: number, requestedOverride?: number) => {
    const requested = requestedOverride ??
        getPositiveIntegerUrlParam('artisanCandidateChecks') ??
        getPositiveIntegerUrlParam('artisanCandidateCheckBudget');
    const budget = Number.isFinite(requested) && requested !== null ?
        requested :
        BAYES_VIEW_CANDIDATE_POOL;
    return Math.max(frameCount, Math.min(BAYES_VIEW_CANDIDATE_POOL, Math.round(budget)));
};

const resolveCaptureAttemptBudget = (acceptedMaskGoal: number, candidateCheckBudget: number) => {
    const requested = getPositiveIntegerUrlParam('artisanMaxCaptureAttempts') ??
        getPositiveIntegerUrlParam('artisanCaptureAttemptBudget');
    if (Number.isFinite(requested) && requested !== null) {
        return Math.max(acceptedMaskGoal, Math.min(candidateCheckBudget, Math.round(requested)));
    }

    const requestedExtra = getPositiveIntegerUrlParam('artisanExtraCaptureAttempts');
    const recoveryBudget = Number.isFinite(requestedExtra) && requestedExtra !== null ?
        Math.max(0, Math.round(requestedExtra)) :
        Math.min(
            BAYES_CAPTURE_ATTEMPT_DEFAULT_MAX_RECOVERY,
            Math.max(
                BAYES_CAPTURE_ATTEMPT_DEFAULT_MIN_RECOVERY,
                Math.ceil(Math.max(0, acceptedMaskGoal - 1) * BAYES_CAPTURE_ATTEMPT_DEFAULT_RECOVERY_RATIO)
            )
        );
    return Math.max(
        acceptedMaskGoal,
        Math.min(candidateCheckBudget, acceptedMaskGoal + recoveryBudget)
    );
};

const resolveMinAcceptedMaskCountForPartialApply = (
    requestedFrameCount: number,
    explicitOverride?: number,
    ratioOverride?: number
) => {
    const requested = Math.max(1, Math.round(requestedFrameCount));
    const explicit = explicitOverride ??
        getPositiveIntegerUrlParam('artisanMinAcceptedMasksForApply') ??
        getPositiveIntegerUrlParam('artisanMinAcceptedMaskCountForApply');
    if (Number.isFinite(explicit) && explicit !== null) {
        return Math.max(1, Math.min(requested, Math.round(explicit)));
    }

    const ratio = ratioOverride ??
        getNumberUrlParam('artisanMinAcceptedMaskRatioForApply') ??
        BAYES_MIN_PARTIAL_APPLY_ACCEPTED_MASK_RATIO;
    const ratioCount = Math.ceil(requested * Math.max(0, Math.min(1, ratio)));
    const refinedCount = requested <= 1 ?
        0 :
        Math.min(requested - 1, BAYES_MIN_PARTIAL_APPLY_REFINED_MASKS);
    return Math.max(1, Math.min(requested, Math.max(ratioCount, refinedCount + 1)));
};

const reservePathFallbackCandidateBudget = (remainingBudget: number) => {
    const remaining = Math.max(0, Math.floor(remainingBudget));
    if (remaining <= BAYES_PROMPT_FOCUS_MIN_SEED_CORE / 12) {
        return 0;
    }

    const proportional = Math.floor(remaining * BAYES_PATH_FALLBACK_RESERVE_RATIO);
    const desired = remaining >= BAYES_PATH_FALLBACK_MIN_RESERVE * 2 ?
        Math.max(BAYES_PATH_FALLBACK_MIN_RESERVE, proportional) :
        proportional;
    const minimumPrimaryBudget = Math.min(remaining, Math.max(8, Math.floor(remaining * 0.45)));
    return Math.max(0, Math.min(desired, remaining - minimumPrimaryBudget));
};

