const shouldUseStrictSequentialEig = (options: ArtisanRunOptions) => {
    if (options.strictSequentialEig === true) {
        return true;
    }
    if (options.strictSequentialEig === false) {
        return false;
    }

    const params = new URLSearchParams(window.location.search);
    if (params.has('artisanMiniBatchEig') || params.has('artisanBatchedEig')) {
        return false;
    }
    if (params.has('artisanStrictSequentialEig')) {
        return getUrlToggle('artisanStrictSequentialEig', true);
    }
    if (params.has('artisanSequentialEig')) {
        return getUrlToggle('artisanSequentialEig', true);
    }

    return true;
};

