        lastEligibleCandidateCount = best.eligible_count;
        lastSkippedCandidateCount = best.skipped_count;
        lastPromptableCandidateCount = best.promptable_count;
        lastUnpromptableCandidateCount = best.unpromptable_count;
        lastPromptValidationCount = best.prompt_validation_count ?? 0;
        lastPromptBuildCount = best.prompt_build_count ?? 0;
