            prefilter_scored_candidates: best.prefilter_scored_count,
            full_score_limit: best.full_score_limit,
            pre_sam_gate_enabled: best.pre_sam_gate_enabled,
            pre_sam_candidate_evaluation_count: best.pre_sam_candidate_evaluation_count,
            pre_sam_eligible_candidates: best.pre_sam_eligible_count,
            pre_sam_rejected_candidates: best.pre_sam_rejected_count,
            pre_sam_rejection_counts: best.pre_sam_rejection_counts,
            promptable_candidates: best.promptable_count,
