	                    pre_sam_rejection_counts: captured.timings.pre_sam_rejection_counts,
	                    pre_sam_relaxed_recovery_count: captured.timings.pre_sam_relaxed_recovery_count,
	                    eig_candidate_refresh_retry_count: captured.timings.eig_candidate_refresh_retry_count,
	                    sam_observation_budget: captured.timings.sam_observation_budget,
                    sam_observation_count: captured.timings.sam_observation_count,
                    seed_sam_observation_count: captured.timings.seed_sam_observation_count,
                    refined_sam_observation_goal: captured.timings.refined_sam_observation_goal,
